def gen_v0c4_perc_clef_key_keeps_clef():
    """PERC clef + Key=-12  →  PERC (percussion has no octave variant)."""
    pre = _patch_tk00('UnknownClefTest'.encode('utf-16-le') + b'\x00\x00')
